export function normalizeDispatcherName(value: string) {
  return value
    .trim()
    .toLocaleLowerCase()
    .replace(/[._-]+/g, ' ')
    .replace(/\s+/g, ' ');
}

const dispatcherIndex = new Map<string, DispatcherProfile | null>();

for (const profile of DISPATCHER_DIRECTORY) {
  for (const alias of [profile.name, ...profile.aliases]) {
    const key = normalizeDispatcherName(alias);
    if (!key) continue;
    const current = dispatcherIndex.get(key);
    dispatcherIndex.set(key, current && current !== profile ? null : profile);
  }
}

export function resolveDispatcherProfile(value: string) {
  if (!value.trim()) return null;
  return dispatcherIndex.get(normalizeDispatcherName(value)) ?? null;
}

